def solve(nums):
    import bisect
    if not nums:
        return 0
    tails = []
    for x in nums:
        # find position to replace in tails (strictly increasing)
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

