def solve(s):
    # Defensive handling: if input is not a string, return 0
    if not isinstance(s, str):
        return 0
    # Accept lowercase by converting to uppercase
    s = s.upper()
    vals = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
