    i = 0
    n = len(s)
    while i < n:
        v = vals.get(s[i])
        if v is None:
            # Invalid character: return 0 (or could raise)
            return 0
        if i+1 < n:
            v_next = vals.get(s[i+1])
            if v_next is None:
                return 0
            if v < v_next:
                total += v_next - v
                i += 2
                continue
        total += v
        i += 1
    return total

