def solve(nums):
    """Return length of the longest strictly increasing subsequence.
    Uses patience sorting with binary search (O(n log n)).
    Handles empty list -> 0.
    """
    import bisect
    if not nums:
        return 0
    tails = []
    for x in nums:
        # Find insertion point for x in tails
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

