def solve(grid):
    # Return 0 for empty grid or grid with no cells
    if not grid:
        return 0
    # Determine number of rows; rows may have varying lengths
    rows = len(grid)
    # Create visited matrix matching each row's length
    visited = [ [False] * len(row) for row in grid ]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            # Bounds check for possibly jagged rows
            if i < 0 or i >= rows or j < 0 or j >= len(grid[i]):
                continue
            if visited[i][j]:
                continue
            # Treat any non‑zero value as land
            if not grid[i][j]:
                continue
            visited[i][j] = True
            # Explore four neighbours
            stack.append((i-1, j))
            stack.append((i+1, j))
            stack.append((i, j-1))
            stack.append((i, j+1))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if not visited[i][j] and grid[i][j]:
                dfs(i, j)
                count += 1
    return count

